                sim.periodManager.addHook('onComplete', function(st) { self._syncUI(st); });
            }
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                sim.eventBus.on('period:undone', function(st) { self._syncUI(st); });
                sim.eventBus.on('language:changed', function() { self._syncUI(sim.state); });
            }
        }

