        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = window.mySimulation.state.domainState;
            var finalRev = ds.revenue;
            var avgEbitda = ds.ebitdaHistory.reduce(function(s, v) { return s + v; }, 0) / ds.ebitdaHistory.length;
            var finalHealth = ds.innovationHealth;
            var avgH1 = ds.h1History.reduce(function(s, v) { return s + v; }, 0) / ds.h1History.length;
            var avgH3 = ds.h3History.reduce(function(s, v) { return s + v; }, 0) / ds.h3History.length;

            var balanceScore = 0;
            if (avgH1 >= 55 && avgH1 <= 70) balanceScore = 25;
            else if (avgH1 >= 45 && avgH1 <= 75) balanceScore = 15;
            else balanceScore = 5;

            var disruptScore = 0;
            var totalInvest = ds.cumulativeDisruptiveInvest + ds.cumulativeSustainingInvest;
            if (totalInvest > 0) {
                var disruptPct = ds.cumulativeDisruptiveInvest / totalInvest;
                if (disruptPct >= 0.35 && disruptPct <= 0.55) disruptScore = 25;
                else if (disruptPct >= 0.25 && disruptPct <= 0.60) disruptScore = 15;
                else disruptScore = 5;
            }

            var killDiscScore = 0;
            if (ds.killTotal >= 1 && ds.killTotal <= 3) killDiscScore = 20;
            else if (ds.killTotal > 3) killDiscScore = 10;
            else killDiscScore = 5;

            var coherenceScore = 0;
            if (ds.zombieTotal <= 2) coherenceScore = 20;
            else if (ds.zombieTotal <= 5) coherenceScore = 12;
            else coherenceScore = 5;

            var commScore = 10;

            var totalScore = this._score(ds);   // same calculator the round loop stores

            var performance = 'Insufficient';
            if (totalScore >= 80) performance = 'Excellent';
            else if (totalScore >= 60) performance = 'Good';
            else if (totalScore >= 40) performance = 'Developing';

            var insights = [];
            if (avgH1 > 70) insights.push('Portfolio was heavily weighted toward Horizon 1 sustaining projects — classic Innovator Dilemma pattern.');
            if (avgH3 < 5) insights.push('Horizon 3 was structurally underfunded — no real options were maintained for long-term disruption defense.');
            if (ds.killTotal === 0) insights.push('No projects were killed during the entire simulation — gate discipline was absent.');
            if (ds.launchedDisruptive >= 2) insights.push('Multiple disruptive projects reached market — strong ambidextrous execution.');
            if (ds.zombieTotal > 4) insights.push('High zombie project count indicates underfunding without kill discipline — the worst of both worlds.');
            if (finalRev > 340) insights.push('Revenue grew above baseline — new project launches offset disruption pressure.');
            if (performance === 'Excellent') insights.push('Outstanding portfolio management — balanced horizons with disciplined gate reviews.');

            return {
                totalScore: totalScore,
                overallScore: totalScore,
                finalRevenue: finalRev,
                avgEbitda: Math.round(avgEbitda * 10) / 10,
                finalHealth: finalHealth,
                balanceScore: balanceScore,
                disruptScore: disruptScore,
                killDiscScore: killDiscScore,
                coherenceScore: coherenceScore,
                projectsKilled: ds.killTotal,
                projectsLaunched: ds.launchedDisruptive + ds.launchedSustaining,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.zombies > 0) return window.mySimulation.t('hint_zombie');
            if (results.h1Pct > 75) return window.mySimulation.t('hint_h1_heavy');
            if (results.disruptiveAlloc < 3) return window.mySimulation.t('hint_no_disruptive');
            if (results.h3Pct >= 8 && results.h3Pct <= 15) return window.mySimulation.t('hint_good_balance');
            return null;
        }

